{"implementation":"def solve(case):
    def require_int(value, field):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(field + " must be an integer")
        return value

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required case field")
    segments = case["segments"]
    budget = require_int(case["budget"], "budget")
    if not isinstance(segments, list):
        raise ValueError("segments must be an array")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()
    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing segment field: " + field)
        name = segment["name"]
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        seen_names.add(name)
        importance = require_int(segment["importance"], "importance")
        minimum = require_int(segment["minimum"], "minimum")
        capacity = require_int(segment["capacity"], "capacity")
        if importance < 0 or minimum < 0 or capacity < 0:
            raise ValueError("segment values must be non-negative")
        if minimum > capacity:
            raise ValueError("minimum exceeds capacity")
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    quota_sum = sum(allocations)
    capacity_sum = sum(capacities)
    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("budget is infeasible")

    remaining = budget - quota_sum
    while remaining:
        best = None
        for index in range(len(segments)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            left = importances[index] * (allocations[best] + 1)
            right = importances[best] * (allocations[index] + 1)
            if left > right:
                best = index
        if best is None:
            raise ValueError("budget is infeasible")
        allocations[best] += 1
        remaining -= 1

    by_name = {names[index]: allocations[index] for index in range(len(names))}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
